INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(5450, 'reconciliation', '/ˌrekənsɪliˈeɪʃən/', 'noun', '{"zh-TW":["帳目核對；對帳"],"en":["the process of comparing two sets of records to ensure they agree"]}', NULL, 'bank reconciliation / account reconciliation / monthly reconciliation', '[{"en":"Monthly bank reconciliation catches discrepancies early.","zh-TW":"月度銀行對帳能早期發現差異。"},{"en":"The accountant performed a reconciliation of all expense accounts.","zh-TW":"會計師對所有費用帳戶進行了對帳。"}]', '{"verb":"reconcile","adjective":"reconciled"}', NULL, 5, 5450, 809),
(5451, 'record', '/rɪˈkɔːrd/', 'verb', '{"zh-TW":["記錄","錄製"],"en":["to write down; to make a note","to capture audio/video"]}', '{"prefix":{"text":"re-","meaning":"again"},"root":{"text":"cord","meaning":"heart (心)"}}', 'keep a record / on record / record-breaking / set a record', '[{"en":"All transactions are recorded in the system.","zh-TW":"所有交易都記錄在系統中。"},{"en":"Sales reached a record high this quarter.","zh-TW":"本季度銷售額創歷史新高。"}]', '{"noun":"record, recording","adjective":"recorded"}', NULL, 2, 5451, 193),
(5452, 'recourse', '/rɪˈkɔːrs/', 'noun', '{"zh-TW":["追索權；補救手段"],"en":["the right to demand compensation from a party if another fails to pay"]}', NULL, 'have recourse against / limited recourse', '[{"en":"The contract includes recourse provisions if the supplier defaults.","zh-TW":"合約包含了供應商違約時的追索權條款。"},{"en":"A non-recourse loan means the lender can only claim the collateral.","zh-TW":"無追索權貸款意味著貸款方只能索取抵押品。"}]', '{"adjective":"non-recourse"}', NULL, 3, 5452, NULL),
(5453, 'recover', '/rɪˈkʌvər/', 'verb', '{"zh-TW":["恢復；找回","恢復；復原","收回"],"en":["to return to a normal state","to get back something lost","to return to normal"]}', '{"prefix":{"text":"re-","meaning":"back (回)"},"root":{"text":"cover","meaning":"cover/get (取得)"},"logic":"取回原來的狀態，即「恢復」。"}', 'recover from / fully recover / recover data; recover from / recover losses / full recovery', '[{"en":"She is recovering from surgery.","zh-TW":"她正在從手術中恢復。"},{"en":"The economy is slowly recovering.","zh-TW":"經濟正在緩慢復甦。"},{"en":"We managed to recover the lost data.","zh-TW":"我們設法恢復了丟失的數據。"}]', '{"noun":"recovery","adjective":"recoverable"}', NULL, 3, 5453, 712),
(5454, 'recovery day', '/''rɪˌkʌvəri deɪ/', 'noun', '{"zh-TW":["恢復日；休息日"],"en":["a day designated for rest and recuperation rather than intense physical exercise"]}', NULL, 'schedule a recovery day / take a recovery day / active recovery day', '[{"en":"Physical trainers recommend at least one recovery day per week for muscle repair.","zh-TW":"體能教練建議每週至少安排一天恢復日以修復肌肉。"},{"en":"She used her recovery day for gentle yoga and stretching.","zh-TW":"她利用恢復日進行輕柔瑜伽和伸展運動。"}]', NULL, NULL, 4, 5454, NULL),
(5455, 'recreation', '/ˌrɛkriˈeɪʃən/', 'noun', '{"zh-TW":["休閒；娛樂"],"en":["activities done for enjoyment"]}', NULL, 'recreation center / outdoor recreation', '[{"en":"The park is used for recreation.","zh-TW":"這個公園用於休閒活動。"},{"en":"Swimming is a popular form of recreation.","zh-TW":"游泳是一種受歡迎的休閒活動。"}]', '{"adjective":"recreational"}', NULL, 4, 5455, NULL),
(5456, 'recruit', '/rɪˈkruːt/', 'verb', '{"zh-TW":["招募；招聘"],"en":["to find new people to join"]}', '{"prefix":{"text":"re-","meaning":"again"},"root":{"text":"cruit","meaning":"grow (生長)"}}', 'recruit new employees / recruit talent / recruitment drive', '[{"en":"We are recruiting for several positions.","zh-TW":"我們正在招聘幾個職位。"},{"en":"The company recruited 50 new graduates.","zh-TW":"公司招募了50名應屆畢業生。"}]', '{"noun":"recruitment, recruiter, recruit"}', NULL, 3, 5456, NULL),
(5457, 'recruitment', '/rɪˈkruːtmənt/', 'noun', '{"zh-TW":["招募；招聘"],"en":["the process of finding and hiring candidates for jobs"]}', NULL, 'recruitment process / recruitment agency / talent recruitment', '[{"en":"The recruitment campaign attracted hundreds of applicants.","zh-TW":"招募活動吸引了數百名申請者。"},{"en":"Online recruitment platforms have transformed hiring.","zh-TW":"線上招募平台改變了招聘方式。"}]', '{"verb":"recruit","noun":"recruiter"}', NULL, 4, 5457, 433),
(5458, 'recurrence', '/rɪˈkɜːrəns/', 'noun', '{"zh-TW":["復發；再發"],"en":["the return of a disease after a period of improvement"]}', NULL, 'prevent recurrence / risk of recurrence / cancer recurrence', '[{"en":"The patient underwent maintenance therapy to reduce the risk of recurrence.","zh-TW":"患者接受了維持療法以降低復發風險。"},{"en":"Regular follow-up monitoring helps detect recurrence early.","zh-TW":"定期隨訪監測有助於早期發現復發。"}]', '{"verb":"recur","adjective":"recurrent"}', NULL, 4, 5458, NULL),
(5459, 'recurring costs', '/rɪˈkɜːrɪŋ kɒsts/', 'noun', '{"zh-TW":["經常性成本"],"en":["ongoing expenses that are incurred regularly as part of business operations"]}', NULL, 'manage recurring costs / reduce recurring costs', '[{"en":"Software subscriptions and rent are major recurring costs.","zh-TW":"軟件訂閱和租金是主要的經常性成本。"},{"en":"Reducing recurring costs directly improves profitability over time.","zh-TW":"減少經常性成本直接改善了長期盈利能力。"}]', '{"opposite":"one-time cost"}', NULL, 5, 5459, NULL),
(5460, 'recurring expense', '/rɪˈkɜːrɪŋ ɪkˈspens/', 'noun', '{"zh-TW":["經常性費用"],"en":["a cost that occurs regularly at set intervals"]}', NULL, 'manage recurring expenses / track recurring expenses', '[{"en":"Rent and utilities are the main recurring expenses.","zh-TW":"租金和水電費是主要的經常性費用。"},{"en":"Recurring expenses should be included in the annual budget plan.","zh-TW":"經常性費用應納入年度預算計劃。"}]', NULL, NULL, 5, 5460, NULL),
(5461, 'recurring revenue', '/rɪˈkɜːrɪŋ ˈrevɪnjuː/', 'noun', '{"zh-TW":["循環收入；經常性收入"],"en":["income generated repeatedly from ongoing subscriptions or contracts"]}', NULL, 'grow recurring revenue / subscription-based recurring revenue', '[{"en":"SaaS companies depend heavily on recurring revenue from subscriptions.","zh-TW":"SaaS公司嚴重依賴訂閱的循環收入。"},{"en":"Recurring revenue provides predictable cash flow for the business.","zh-TW":"循環收入為業務提供了可預測的現金流。"}]', NULL, NULL, 5, 5461, NULL),
(5462, 'recursive', '/rɪˈkɜːrsɪv/', 'adjective', '{"zh-TW":["遞迴的；循環的"],"en":["relating to a procedure that repeats itself; self-referential"]}', NULL, 'recursive algorithm / recursive process / recursive function', '[{"en":"A recursive function calls itself to solve a smaller version of the problem.","zh-TW":"遞迴函數通過調用自身來解決問題的較小版本。"},{"en":"Learning is a recursive process of building on prior knowledge.","zh-TW":"學習是建立在先前知識基礎上的遞迴過程。"}]', '{"noun":"recursion","adverb":"recursively"}', NULL, 3, 5462, NULL),
(5463, 'recycling', '/rɪˈsaɪklɪŋ/', 'noun', '{"zh-TW":["回收再利用"],"en":["converting waste into reusable material"]}', NULL, 'recycling program / recycling rate', '[{"en":"The city launched a new recycling program last year.","zh-TW":"市政府去年推出了新的回收計劃。"},{"en":"Recycling aluminum cans saves significant energy.","zh-TW":"回收鋁罐可節省大量能源。"}]', '{"verb":"recycle","adjective":"recyclable"}', NULL, 3, 5463, NULL),
(5464, 'redemption', '/rɪˈdempʃən/', 'noun', '{"zh-TW":["贖回；償還"],"en":["the action of repaying or regaining possession of something in exchange for payment"]}', NULL, 'bond redemption / redemption date / early redemption', '[{"en":"The bond is scheduled for redemption in five years.","zh-TW":"債券預定五年後贖回。"},{"en":"Early redemption may be subject to a penalty fee.","zh-TW":"提前贖回可能需支付違約金。"}]', '{"verb":"redeem","adjective":"redeemable"}', NULL, 4, 5464, NULL),
(5465, 'redress', '/rɪˈdres/', 'noun', '{"zh-TW":["補救；救濟；糾正"],"en":["the act of rectifying an injustice; compensation for a wrong"]}', NULL, 'seek redress / redress grievances / right of redress', '[{"en":"Consumers have the right to seek redress when companies fail to deliver services as promised.","zh-TW":"當公司未能按承諾提供服務時，消費者有權尋求補救。"},{"en":"The court awarded financial redress to victims of the illegal data breach.","zh-TW":"法院向非法數據洩露的受害者判給財務補救。"}]', '{"verb":"redress"}', NULL, 3, 5465, NULL),
(5466, 'reduce', '/rɪˈdjuːs/', 'verb', '{"zh-TW":["減少；降低"],"en":["to make smaller in size or amount"]}', '{"prefix":{"text":"re-","meaning":"back"},"root":{"text":"duce","meaning":"lead (引導)"}}', 'reduce costs / reduce emissions / reduce the risk', '[{"en":"We need to reduce operating costs.","zh-TW":"我們需要降低營運成本。"},{"en":"The new policy aims to reduce emissions.","zh-TW":"新政策旨在減少排放。"}]', '{"noun":"reduction"}', NULL, 2, 5466, 194),
(5467, 'reduction', 'rɪˈdʌkʃən', 'noun', '{"zh-TW":["減少；降低","縮減"],"en":["a decrease in amount","the act of making smaller"]}', NULL, 'cost reduction/price reduction', '[{"en":"Cost reduction is a key business objective.","zh-TW":"降低成本是主要的業務目標。"}]', '{"verb":"reduce","adjective":"reduced","adverb":"reducibly"}', NULL, 3, 5467, NULL),
(5468, 'reductive', '/rɪˈdʌktɪv/', 'adjective', '{"zh-TW":["簡化的；過度簡化的"],"en":["tending to present something in an overly simplified way"]}', NULL, 'reductive argument / reductive approach / reductive thinking', '[{"en":"His reductive analysis ignored the complexity of the issue.","zh-TW":"他的過度簡化分析忽略了問題的複雜性。"},{"en":"Reducing poverty to a single cause is a reductive approach.","zh-TW":"將貧困歸結為單一原因是一種過度簡化的方法。"}]', '{"noun":"reduction","adverb":"reductively"}', NULL, 3, 5468, NULL),
(5469, 'redundancy', '/rɪˈdʌndənsi/', 'noun', '{"zh-TW":["裁員；多餘"],"en":["the elimination of a job because it is no longer needed"]}', NULL, 'compulsory redundancy / voluntary redundancy / face redundancy', '[{"en":"Automation led to widespread redundancy in the factory.","zh-TW":"自動化導致工廠出現大規模裁員。"},{"en":"She took voluntary redundancy and started her own business.","zh-TW":"她選擇自願離職並創辦了自己的事業。"}]', '{"adjective":"redundant"}', NULL, 4, 5469, NULL),
(5470, 'redundancy package', '/rɪˈdʌndənsi ˈpækɪdʒ/', 'noun', '{"zh-TW":["裁員補償方案"],"en":["a financial settlement offered to employees being made redundant"]}', NULL, 'offer a redundancy package / accept a redundancy package', '[{"en":"The company offered a generous redundancy package to affected employees.","zh-TW":"公司向受影響的員工提供了慷慨的裁員補償方案。"},{"en":"The redundancy package included three months pay and career support.","zh-TW":"裁員補償方案包括三個月薪資和職業支持。"}]', NULL, NULL, 5, 5470, NULL),
(5471, 'redundancy payment', '/rɪˈdʌndənsi ˈpeɪmənt/', 'noun', '{"zh-TW":["裁員賠償；遣散費"],"en":["compensation paid to employees when their role is eliminated due to restructuring"]}', NULL, 'receive redundancy payment / redundancy payment calculation', '[{"en":"Employees affected by the restructuring received a redundancy payment.","zh-TW":"受重組影響的員工收到了遣散費。"},{"en":"Redundancy payments are calculated based on years of service.","zh-TW":"遣散費根據服務年限計算。"}]', NULL, NULL, 5, 5471, NULL),
(5472, 'redundant', '/rɪˈdʌndənt/', 'adjective', '{"zh-TW":["多餘的；被裁員的"],"en":["no longer needed; also describes a worker whose job has been eliminated"]}', NULL, 'made redundant / redundant position / redundant system', '[{"en":"He was made redundant when his department was downsized.","zh-TW":"他的部門縮編後，他遭到了裁員。"},{"en":"The redundant data backup system provided extra security.","zh-TW":"多餘的資料備份系統提供了額外的安全保障。"}]', '{"verb":"make redundant","noun":"redundancy"}', NULL, 3, 5472, NULL),
(5473, 'refactoring', '/riːˈfæktərɪŋ/', 'noun', '{"zh-TW":["重構"],"en":["restructuring existing code without changing its external behavior"]}', NULL, 'code refactoring / perform refactoring / refactoring session', '[{"en":"Regular refactoring keeps the codebase maintainable and readable.","zh-TW":"定期重構使程式碼庫保持可維護性和可讀性。"},{"en":"The team allocated one sprint for refactoring the payment module.","zh-TW":"團隊分配了一個衝刺用於重構支付模組。"}]', '{"verb":"refactor","adjective":"refactored"}', NULL, 4, 5473, NULL),
(5474, 'refer', '/rɪˈfɜːr/', 'verb', '{"zh-TW":["提到；參考","轉介"],"en":["to mention","to direct someone"]}', '{"prefix":{"text":"re-","meaning":"back"},"root":{"text":"fer","meaning":"carry (攜帶)"}}', 'refer to / refer sb. to / with reference to', '[{"en":"Please refer to the user manual.","zh-TW":"請參考用戶手冊。"},{"en":"I was referred to the HR department.","zh-TW":"我被轉介到人資部門。"}]', '{"noun":"reference, referral, referee"}', NULL, 2, 5474, 51),
(5475, 'referee', '/ˌrɛfəˈriː/', 'noun', '{"zh-TW":["裁判"],"en":["a person who makes sure rules are followed in a game"]}', NULL, 'referee a match / referee''s decision', '[{"en":"The referee blew the whistle.","zh-TW":"裁判吹響了哨子。"},{"en":"The referee''s decision is final.","zh-TW":"裁判的決定是最終的。"}]', NULL, NULL, 3, 5475, NULL),
(5476, 'reference', '/ˈrɛfərəns/', 'noun', '{"zh-TW":["參考；參照","推薦信"],"en":["a source of information","a letter of recommendation"]}', '{"prefix":{"text":"re-","meaning":"back"},"root":{"text":"fer","meaning":"carry"},"suffix":{"text":"-ence","meaning":"名詞後綴"}}', 'for reference / reference number / provide references', '[{"en":"Please keep this for future reference.","zh-TW":"請保留此文件以供未來參考。"},{"en":"Can you provide two professional references?","zh-TW":"你能提供兩份專業推薦嗎？"}]', '{"verb":"refer"}', NULL, 3, 5476, NULL),
(5477, 'reference check', '/ˈrefrəns tʃek/', 'noun', '{"zh-TW":["背景調查；推薦人查核"],"en":["the process of verifying a job candidate''s work history through previous employers"]}', NULL, 'conduct a reference check / reference check process', '[{"en":"Reference checks confirmed the candidate had an excellent performance record.","zh-TW":"背景調查確認了候選人有出色的績效記錄。"},{"en":"All final candidates undergo a reference check before an offer is made.","zh-TW":"所有最終候選人在提出邀約前都要接受推薦人查核。"}]', NULL, NULL, 5, 5477, NULL),
(5478, 'reference number', '/ˈrɛfrəns ˈnʌmbər/', 'noun', '{"zh-TW":["參考號碼；查詢編號"],"en":["a number assigned to identify a specific transaction or record"]}', NULL, 'provide a reference number / quote your reference number', '[{"en":"Please quote your reference number when contacting customer service.","zh-TW":"聯繫客服時請提供您的參考號碼。"},{"en":"The reference number is located on the top of your invoice.","zh-TW":"參考號碼位於您的發票頂部。"}]', NULL, NULL, 5, 5478, NULL),
(5479, 'reference rate', '/ˈrefrəns reɪt/', 'noun', '{"zh-TW":["參考利率；基準利率"],"en":["a benchmark interest rate used to price financial instruments"]}', NULL, 'set a reference rate / reference rate change', '[{"en":"Variable loans are priced based on a reference rate plus a spread.","zh-TW":"浮動貸款根據參考利率加差價定價。"},{"en":"Changes in the reference rate affect all floating-rate debt instruments.","zh-TW":"參考利率的變化影響了所有浮動利率債務工具。"}]', '{"synonym":"benchmark rate"}', NULL, 5, 5479, NULL),
(5480, 'referral', '/rɪˈfɜːrəl/', 'noun', '{"zh-TW":["轉介；轉診"],"en":["a direction of a patient to a specialist"]}', NULL, 'get a referral / specialist referral', '[{"en":"You need a referral from your primary doctor to see a specialist.","zh-TW":"您需要主治醫師的轉介才能看專科醫生。"},{"en":"The referral was approved by the insurance company.","zh-TW":"轉介已獲保險公司批准。"}]', '{"verb":"refer"}', NULL, 3, 5480, NULL),
(5481, 'refinancing', '/ˌriːˈfaɪnænsɪŋ/', 'noun', '{"zh-TW":["再融資"],"en":["replacing an existing loan with a new one, usually at better terms"]}', NULL, 'pursue refinancing / complete refinancing', '[{"en":"The company completed refinancing at a lower interest rate.","zh-TW":"公司以較低的利率完成了再融資。"},{"en":"Refinancing reduced annual debt servicing costs by $2 million.","zh-TW":"再融資將年度償債成本減少了200萬元。"}]', '{"verb":"refinance"}', NULL, 4, 5481, NULL),
(5482, 'refine', '/rɪˈfaɪn/', 'verb', '{"zh-TW":["完善；改善；提煉"],"en":["to make minor improvements to something"]}', NULL, 'refine a process / refine the strategy', '[{"en":"The team refined the proposal based on feedback.","zh-TW":"團隊根據反饋完善了提案。"},{"en":"Refining the manufacturing process reduced defect rates.","zh-TW":"改善製造流程降低了缺陷率。"}]', '{"noun":"refinement","adjective":"refined"}', NULL, 2, 5482, NULL),
(5483, 'reflect', '/rɪˈflɛkt/', 'verb', '{"zh-TW":["反映；反射","反思"],"en":["to show or express","to think carefully"]}', '{"prefix":{"text":"re-","meaning":"back"},"root":{"text":"flect","meaning":"bend (彎曲)"}}', 'reflect on / reflect changes / reflect the views', '[{"en":"The report reflects the current market conditions.","zh-TW":"報告反映了當前市場狀況。"},{"en":"Take time to reflect on your progress.","zh-TW":"花時間反思你的進展。"}]', '{"noun":"reflection","adjective":"reflective"}', NULL, 3, 5483, NULL),
(5484, 'reflexive', '/rɪˈfleksɪv/', 'adjective', '{"zh-TW":["反身的；自省的"],"en":["directed back on itself; relating to critical self-awareness"]}', NULL, 'reflexive thinking / reflexive practice / reflexive research', '[{"en":"Reflexive research requires the researcher to examine their own biases.","zh-TW":"自省性研究要求研究員審視自己的偏見。"},{"en":"Reflexive thinking helps professionals learn from their own experiences.","zh-TW":"反身思考幫助專業人士從自身經驗中學習。"}]', '{"noun":"reflexivity","adverb":"reflexively"}', NULL, 3, 5484, NULL),
(5485, 'reflexivity', '/ˌrɪflekˈsɪvɪti/', 'noun', '{"zh-TW":["反身性；自我反思能力"],"en":["the capacity of social systems to reflect on themselves"]}', NULL, 'researcher reflexivity / reflexivity in methods / critical reflexivity', '[{"en":"Reflexivity in research requires the scholar to examine their own position.","zh-TW":"研究中的反身性要求學者審視自己的立場。"},{"en":"Reflexivity distinguishes qualitative research from positivist approaches.","zh-TW":"反身性將質性研究與實證主義方法區別開來。"}]', '{"adjective":"reflexive","adverb":"reflexively"}', NULL, 4, 5485, NULL),
(5486, 'reforestation', '/ˌriːˌfɒrɪˈsteɪʃən/', 'noun', '{"zh-TW":["植樹造林；重新造林"],"en":["planting trees in an area where forest has been removed"]}', NULL, 'reforestation project / reforestation effort', '[{"en":"The charity funds reforestation projects in deforested areas.","zh-TW":"該慈善機構資助毀林地區的植樹造林項目。"},{"en":"Reforestation helps restore biodiversity and absorb carbon.","zh-TW":"植樹造林有助於恢復生物多樣性和吸收碳。"}]', '{"verb":"reforest","adjective":"reforested"}', NULL, 5, 5486, NULL),
(5487, 'reform', '/rɪˈfɔːrm/', 'noun', '{"zh-TW":["改革"],"en":["a change made to improve a system","a change made to improve something"]}', '{"prefix":{"text":"re-","meaning":"again (再次)"},"root":{"text":"form","meaning":"form/shape (形成)"},"logic":"重新形成，即「改革」。"}', 'education reform / tax reform / reform the system; economic reform / reform the system / tax reform', '[{"en":"The government introduced economic reforms.","zh-TW":"政府推行了經濟改革。"},{"en":"Healthcare reform is urgently needed.","zh-TW":"醫療改革迫在眉睫。"},{"en":"The government announced major tax reforms.","zh-TW":"政府宣布了重大稅制改革。"},{"en":"Healthcare reform is a priority.","zh-TW":"醫療改革是優先事項。"}]', '{"verb":"reform","noun2":"reformer","noun":"reformer"}', NULL, 2, 5487, NULL),
(5488, 'reformulate', '/riːˈfɔːrmjʊleɪt/', 'verb', '{"zh-TW":["重新制定；重新配製"],"en":["to revise or change the formulation of a plan, policy, or product"]}', NULL, 'reformulate the strategy / reformulate the product', '[{"en":"The company reformulated the product to remove allergens.","zh-TW":"公司重新配製了產品以去除過敏原。"},{"en":"Management reformulated its growth strategy after market conditions changed.","zh-TW":"市場條件變化後，管理層重新制定了增長策略。"}]', '{"noun":"reformulation","adjective":"reformulated"}', NULL, 4, 5488, NULL),
(5489, 'refund', '/ˈriːfʌnd/', 'noun', '{"zh-TW":["退款"],"en":["money returned to a buyer"]}', '{"prefix":{"text":"re-","meaning":"back (回)"},"root":{"text":"fund","meaning":"pour/money (注入/資金)"},"logic":"把錢倒回去，即「退款」。"}', 'full refund / request a refund; full refund / request a refund / refund policy', '[{"en":"I would like to request a refund.","zh-TW":"我想要求退款。"},{"en":"They issued a full refund within 24 hours.","zh-TW":"他們在24小時內全額退款。"},{"en":"We will issue a full refund.","zh-TW":"我們將全額退款。"},{"en":"Please check our refund policy.","zh-TW":"請查看我們的退款政策。"}]', '{"verb":"refund","adjective":"refundable"}', NULL, 2, 5489, 195),
(5490, 'refund policy', '/ˈriːfʌnd ˈpɒlɪsi/', 'noun', '{"zh-TW":["退款政策"],"en":["the rules governing when and how customers can get money back"]}', NULL, 'review the refund policy / communicate the refund policy', '[{"en":"The company updated its refund policy to a 30-day returns window.","zh-TW":"公司將退款政策更新為30天退貨窗口。"},{"en":"Clear refund policies build customer trust and reduce disputes.","zh-TW":"清晰的退款政策建立了客戶信任並減少了糾紛。"}]', NULL, NULL, 5, 5490, NULL),
(5491, 'refundable deposit', '/rɪˈfʌndəbl dɪˈpɒzɪt/', 'noun', '{"zh-TW":["可退還押金"],"en":["a sum of money paid as security that will be returned when conditions are met"]}', NULL, 'pay a refundable deposit / claim back the refundable deposit', '[{"en":"A refundable deposit of $500 is required to hold the rental equipment.","zh-TW":"需要500元的可退還押金來預留租用設備。"},{"en":"The refundable deposit was returned in full after the lease term ended.","zh-TW":"租賃期限結束後，可退還押金全額退還了。"}]', '{"opposite":"non-refundable deposit"}', NULL, 5, 5491, NULL),
(5492, 'refute', '/rɪˈfjuːt/', 'verb', '{"zh-TW":["反駁；駁倒"],"en":["to prove a statement or person to be wrong"]}', NULL, 'refute an argument / refute a claim / refute the evidence', '[{"en":"The study refutes the commonly held assumption about consumer behavior.","zh-TW":"該研究反駁了關於消費者行為的普遍假設。"},{"en":"He could not refute the data presented by the opposing team.","zh-TW":"他無法反駁對方團隊提出的數據。"}]', '{"noun":"refutation","adjective":"irrefutable"}', NULL, 2, 5492, NULL),
(5493, 'regard', '/rɪˈɡɑːrd/', 'verb', '{"zh-TW":["認為；看待"],"en":["to consider; to think of"]}', '{"prefix":{"text":"re-","meaning":"again"},"root":{"text":"gard","meaning":"watch (看)"}}', 'regard as / with regard to / in this regard / regardless', '[{"en":"She is widely regarded as an expert.","zh-TW":"她被廣泛認為是專家。"},{"en":"With regard to your inquiry, please see below.","zh-TW":"關於您的詢問，請見下方。"}]', '{"noun":"regard, regards","preposition":"regarding"}', NULL, 2, 5493, NULL),
(5494, 'regarding', '/rɪˈɡɑːrdɪŋ/', 'preposition', '{"zh-TW":["關於；有關"],"en":["with reference to; concerning"]}', NULL, 'regarding the matter / regarding your inquiry', '[{"en":"I am writing regarding the invoice dated March 10th.","zh-TW":"我寫信是關於3月10日的發票。"},{"en":"Regarding your inquiry, please see the attached response.","zh-TW":"關於您的查詢，請參閱附件的回覆。"}]', '{"verb":"regard","noun":"regard"}', NULL, 3, 5494, NULL),
(5495, 'regardless', '/rɪˈɡɑːrdləs/', 'adverb', '{"zh-TW":["不管；無論如何"],"en":["without being affected by"]}', '{"prefix":{"text":"re-","meaning":"again"},"root":{"text":"gard","meaning":"watch"},"suffix":{"text":"-less","meaning":"without (無)"}}', 'regardless of / regardless of the cost', '[{"en":"We will proceed regardless of the obstacles.","zh-TW":"無論有什麼障礙我們都將繼續。"},{"en":"The rule applies regardless of seniority.","zh-TW":"規則不論資歷均適用。"}]', NULL, NULL, 4, 5495, NULL),
(5496, 'region', '/ˈriːdʒən/', 'noun', '{"zh-TW":["地區；區域"],"en":["a particular area or part"]}', NULL, 'in the region / regional office / Asia-Pacific region', '[{"en":"The company has offices in every region.","zh-TW":"公司在每個地區都有辦公室。"},{"en":"Economic growth varies by region.","zh-TW":"經濟增長因地區而異。"}]', '{"adjective":"regional","adverb":"regionally"}', NULL, 2, 5496, NULL),
(5497, 'regional manager', '/ˈriːdʒənl ˈmænɪdʒər/', 'noun', '{"zh-TW":["區域經理"],"en":["a manager responsible for business operations in a specific geographic region"]}', NULL, 'appoint a regional manager / regional manager responsibilities', '[{"en":"The regional manager oversees six branch offices.","zh-TW":"區域經理監管六個分支辦公室。"},{"en":"The regional manager reports directly to the vice president of operations.","zh-TW":"區域經理直接向運營副總裁匯報。"}]', NULL, NULL, 5, 5497, NULL),
(5498, 'regional office', '/ˈriːdʒənl ˈɒfɪs/', 'noun', '{"zh-TW":["地區辦公室；區域辦事處"],"en":["an office representing a company in a specific geographic area"]}', NULL, 'open a regional office / regional office operations', '[{"en":"The company opened a regional office in Singapore to cover Southeast Asia.","zh-TW":"公司在新加坡開設了地區辦公室以覆蓋東南亞。"},{"en":"Regional offices report monthly results to headquarters.","zh-TW":"地區辦公室每月向總部報告業績。"}]', NULL, NULL, 5, 5498, NULL),
(5499, 'register', '/ˈredʒɪstər/', 'noun', '{"zh-TW":["收銀機；登記","登記；註冊"],"en":["a cash register","to officially record information","to officially record or enroll"]}', '{"root":{"text":"gest","meaning":"carry (攜帶)"},"prefix":{"text":"re-","meaning":"back (回)"},"logic":"帶回紀錄，指登記或收銀機。"}', 'cash register / register for a course; register for / register a complaint / registered office', '[{"en":"The cashier opened the register to make change.","zh-TW":"收銀員打開收銀機找零。"},{"en":"Please register at the front desk.","zh-TW":"請在前台登記。"},{"en":"You must register before attending the event.","zh-TW":"參加活動前必須註冊。"},{"en":"The company is registered in Delaware.","zh-TW":"公司在德拉瓦州註冊。"}]', '{"noun":"registration","adjective":"registered"}', NULL, 3, 5499, 52);
INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(5500, 'registered office', '/ˈredʒɪstərd ˈɒfɪs/', 'noun', '{"zh-TW":["注冊辦公室；法定地址"],"en":["the official address of a company as registered with the government"]}', NULL, 'establish a registered office / registered office address', '[{"en":"The registered office address must be available to the public.","zh-TW":"注冊辦公室地址必須向公眾公開。"},{"en":"Companies must notify the authorities if their registered office changes.","zh-TW":"如果公司的注冊辦公室地址有變更，必須通知有關機構。"}]', NULL, NULL, 5, 5500, NULL),
(5501, 'registered trademark', '/ˈredʒɪstərd ˈtreɪdmɑːrk/', 'noun', '{"zh-TW":["注冊商標"],"en":["a legally protected symbol, word, or phrase identifying a brand''s products"]}', NULL, 'obtain a registered trademark / registered trademark infringement', '[{"en":"Using another company''s registered trademark without permission is illegal.","zh-TW":"未經許可使用另一家公司的注冊商標是非法的。"},{"en":"A registered trademark provides exclusive rights to use the mark in commerce.","zh-TW":"注冊商標提供了在商業中使用該標誌的獨家權利。"}]', '{"symbol":"®","synonym":"trademark"}', NULL, 5, 5501, NULL),
(5502, 'registration', 'ˌrɛdʒɪˈstreɪʃən', 'noun', '{"zh-TW":["登記；註冊","掛號"],"en":["the process of signing up","an official record"]}', NULL, 'online registration/event registration', '[{"en":"Registration closes on Friday.","zh-TW":"登記在週五截止。"}]', '{"verb":"register","adjective":"registered"}', NULL, 4, 5502, 613),
(5503, 'registration desk', '/ˌrɛdʒɪˈstreɪʃən dɛsk/', 'noun', '{"zh-TW":["報名處；登記台"],"en":["a table or counter where attendees register for an event"]}', NULL, 'check in at the registration desk / registration desk hours', '[{"en":"Please check in at the registration desk upon arrival.","zh-TW":"抵達時請在報名處辦理登記。"},{"en":"The registration desk opens one hour before the event begins.","zh-TW":"報名處在活動開始前一小時開放。"}]', NULL, NULL, 5, 5503, NULL),
(5504, 'regression testing', '/rɪˈɡreʃən ˈtestɪŋ/', 'noun', '{"zh-TW":["回歸測試"],"en":["testing to ensure that previously working software still functions after changes"]}', NULL, 'perform regression testing / automated regression testing / regression test suite', '[{"en":"Regression testing prevents new code changes from breaking existing features.","zh-TW":"回歸測試防止新的代碼更改破壞現有功能。"},{"en":"The CI pipeline runs regression testing automatically on each commit.","zh-TW":"CI管道在每次提交時自動運行回歸測試。"}]', '{"verb":"regression test"}', NULL, 5, 5504, NULL),
(5505, 'regulate', '/ˈrɛɡjuleɪt/', 'verb', '{"zh-TW":["規範；調節","監管；調節"],"en":["to control something by rules","to control or supervise by rules","to control by rules"]}', '{"root":{"text":"regul","meaning":"rule (規則)"},"suffix":{"text":"-ate","meaning":"make (使)"},"logic":"使其按規則運行，即「規範」。"}', 'regulate industry / government regulated; regulate the industry / regulate temperature; regulate the industry / strictly regulated', '[{"en":"The government regulates the banking industry.","zh-TW":"政府規範銀行業。"},{"en":"This law regulates food safety.","zh-TW":"這項法律規範食品安全。"},{"en":"This thermostat regulates room temperature.","zh-TW":"這個恆溫器調節室溫。"},{"en":"The government regulates the financial sector.","zh-TW":"政府監管金融業。"},{"en":"Prices are regulated by market forces.","zh-TW":"價格由市場力量調節。"}]', '{"noun":"regulation","noun2":"regulator","adjective":"regulatory"}', NULL, 3, 5505, NULL),
(5506, 'regulation', '/ˌrɛɡjuˈleɪʃən/', 'noun', '{"zh-TW":["法規；規定"],"en":["an official rule or law"]}', '{"root":{"text":"regul","meaning":"rule (規則)"},"suffix":{"text":"-ation","meaning":"行為"}}', 'comply with regulations / safety regulations / government regulation', '[{"en":"All companies must comply with safety regulations.","zh-TW":"所有公司必須遵守安全法規。"},{"en":"New regulations take effect next month.","zh-TW":"新法規下月生效。"}]', '{"verb":"regulate","adjective":"regulatory","noun":"regulator"}', NULL, 4, 5506, 434),
(5507, 'regulatory approval', '/ˌreɡjʊˈleɪtɔːri əˈpruːvəl/', 'noun', '{"zh-TW":["監管批准"],"en":["official permission from a regulatory body to proceed with an action"]}', NULL, 'obtain regulatory approval / pending regulatory approval', '[{"en":"The drug cannot be sold until regulatory approval is granted.","zh-TW":"在獲得監管批准之前，藥物不能出售。"},{"en":"The merger was completed after receiving regulatory approval.","zh-TW":"在獲得監管批准後完成了合併。"}]', NULL, NULL, 5, 5507, NULL),
(5508, 'regulatory authority', '/ˌreɡjəˈleɪtəri ɔːˈθɒrɪti/', 'noun', '{"zh-TW":["監管機構"],"en":["a government body responsible for overseeing a specific industry or sector"]}', NULL, 'comply with the regulatory authority / regulatory authority approval', '[{"en":"The drug required approval from the regulatory authority before launch.","zh-TW":"藥物在上市之前需要監管機構的批准。"},{"en":"Violations may result in sanctions imposed by the regulatory authority.","zh-TW":"違規行為可能導致監管機構實施制裁。"}]', NULL, NULL, 5, 5508, NULL),
(5509, 'regulatory body', '/ˈreɡjʊlətɔːri ˈbɒdi/', 'noun', '{"zh-TW":["監管機構"],"en":["an official organization responsible for overseeing a particular industry"]}', NULL, 'report to a regulatory body / comply with the regulatory body', '[{"en":"All financial institutions must be registered with the relevant regulatory body.","zh-TW":"所有金融機構必須向相關監管機構登記。"},{"en":"The regulatory body launched an investigation into the trading practices.","zh-TW":"監管機構對交易行為展開了調查。"}]', NULL, NULL, 5, 5509, NULL),
(5510, 'regulatory burden', '/ˈreɡjʊlətəri ˈbɜːrdən/', 'noun', '{"zh-TW":["監管負擔"],"en":["the cost and effort required to comply with government regulations"]}', NULL, 'reduce regulatory burden / regulatory burden on business / heavy regulatory burden', '[{"en":"Small businesses often struggle with the regulatory burden of compliance.","zh-TW":"小型企業通常難以應付合規的監管負擔。"},{"en":"Policymakers must balance consumer protection with the regulatory burden.","zh-TW":"政策制定者必須在消費者保護和監管負擔之間取得平衡。"}]', NULL, NULL, 5, 5510, NULL),
(5511, 'regulatory capture', '/ˈreɡjʊlətəri ˈkæptʃər/', 'noun', '{"zh-TW":["監管俘獲"],"en":["when a regulatory agency advances the interests of those it is supposed to regulate"]}', NULL, 'prevent regulatory capture / problem of regulatory capture / address regulatory capture', '[{"en":"Regulatory capture occurs when industries successfully influence their overseers.","zh-TW":"當行業成功影響其監管機構時，就會發生監管俘獲。"},{"en":"Revolving doors between government and industry can lead to regulatory capture.","zh-TW":"政府和工業界之間的旋轉門可能導致監管俘獲。"}]', NULL, NULL, 5, 5511, NULL),
(5512, 'regulatory change', '/ˌreɡjʊˈleɪtɔːri tʃeɪndʒ/', 'noun', '{"zh-TW":["監管變更"],"en":["a modification to laws or rules governing an industry"]}', NULL, 'prepare for regulatory change / adapt to regulatory changes', '[{"en":"The company updated its processes to comply with the regulatory change.","zh-TW":"公司更新了流程以遵守監管變更。"},{"en":"Regulatory changes in data protection required major system upgrades.","zh-TW":"資料保護方面的監管變更需要重大系統升級。"}]', NULL, NULL, 5, 5512, NULL),
(5513, 'regulatory compliance', '/ˌreɡjʊˈleɪtəri kəmˈplaɪəns/', 'noun', '{"zh-TW":["監管合規"],"en":["adhering to laws, regulations, and standards governing business activities"]}', NULL, 'ensure regulatory compliance / regulatory compliance framework', '[{"en":"The company invested in regulatory compliance systems.","zh-TW":"公司投資了監管合規系統。"},{"en":"Failure to achieve regulatory compliance resulted in substantial fines.","zh-TW":"未能達到監管合規導致了重大罰款。"}]', NULL, NULL, 5, 5513, NULL),
(5514, 'regulatory framework', '/ˌreɡjʊlətəri ˈfreɪmwɜːrk/', 'noun', '{"zh-TW":["監管框架"],"en":["the set of laws, guidelines, and standards governing an industry or sector"]}', NULL, 'comply with the regulatory framework / regulatory framework update', '[{"en":"Financial institutions must operate within the regulatory framework.","zh-TW":"金融機構必須在監管框架內運營。"},{"en":"Changes to the regulatory framework affect compliance costs and practices.","zh-TW":"監管框架的變化影響了合規成本和做法。"}]', NULL, NULL, 5, 5514, NULL),
(5515, 'regulatory sandbox', '/ˈreɡjʊlətəri ˈsændbɒks/', 'noun', '{"zh-TW":["監管沙盒"],"en":["a framework allowing businesses to test innovations under relaxed regulations"]}', NULL, 'enter a regulatory sandbox / regulatory sandbox program / regulatory sandbox trial', '[{"en":"The fintech firm tested its payment product within a regulatory sandbox.","zh-TW":"金融科技公司在監管沙盒中測試其支付產品。"},{"en":"Regulatory sandboxes allow innovation while protecting consumers.","zh-TW":"監管沙盒允許創新同時保護消費者。"}]', NULL, NULL, 5, 5515, NULL),
(5516, 'rehabilitate', '/''riːhəˈbɪlɪteɪt/', 'verb', '{"zh-TW":["康復；復健"],"en":["to restore to health or normal life through training and therapy after illness or injury"]}', NULL, 'rehabilitate an injury / rehabilitate fully / sports rehabilitation', '[{"en":"The athlete worked with a physiotherapist to rehabilitate his knee injury.","zh-TW":"這位運動員與物理治療師合作，對膝關節損傷進行復健。"},{"en":"After surgery, it took six months to fully rehabilitate and return to competition.","zh-TW":"手術後，花了六個月時間完全復健並重返賽場。"}]', '{"noun":"rehabilitation"}', NULL, 4, 5516, NULL),
(5517, 'rehabilitation', '/ˌriːhəˌbɪlɪˈteɪʃən/', 'noun', '{"zh-TW":["復健；康復治療"],"en":["therapy to restore health or ability after injury"]}', NULL, 'physical rehabilitation / rehabilitation program', '[{"en":"She attended rehabilitation sessions twice a week.","zh-TW":"她每週兩次參加復健課程。"},{"en":"The rehabilitation program helped him regain full mobility.","zh-TW":"復健計劃幫助他恢復了完全的行動能力。"}]', '{"verb":"rehabilitate","adjective":"rehabilitated"}', NULL, 5, 5517, NULL),
(5518, 'rehabilitation program', '/''riːˌhæbɪlɪˌteɪʃən ˌprəʊɡræm/', 'noun', '{"zh-TW":["康復計劃；復健計劃"],"en":["a structured set of therapeutic activities designed to restore an injured person''s physical functioning"]}', NULL, 'complete a rehabilitation program / design a rehabilitation program / enter a rehabilitation program', '[{"en":"After knee surgery, she followed a six-month rehabilitation program to regain full mobility.","zh-TW":"膝蓋手術後，她遵循了六個月的康復計劃，以恢復完整的活動能力。"},{"en":"A well-designed rehabilitation program helps athletes return to training safely.","zh-TW":"設計良好的康復計劃幫助運動員安全地恢復訓練。"}]', '{"verb":"rehabilitate","noun":"rehabilitation"}', NULL, 5, 5518, NULL),
(5519, 'rehearsal', '/rɪˈhɜːrsəl/', 'noun', '{"zh-TW":["排練；彩排"],"en":["a practice session before a performance"]}', NULL, 'dress rehearsal / rehearsal room', '[{"en":"We have rehearsal every evening this week.","zh-TW":"這週我們每晚都有排練。"},{"en":"The dress rehearsal is tomorrow.","zh-TW":"彩排在明天。"}]', '{"verb":"rehearse"}', NULL, 3, 5519, NULL),
(5520, 'reimbursable', '/ˌriːɪmˈbɜːrsəbəl/', 'adjective', '{"zh-TW":["可報銷的"],"en":["able to be repaid or compensated"]}', NULL, 'reimbursable expense / reimbursable cost', '[{"en":"Travel costs are reimbursable upon submission of receipts.","zh-TW":"提交收據後差旅費用可以報銷。"},{"en":"Check which expenses are reimbursable under the policy.","zh-TW":"請查看政策下哪些費用可以報銷。"}]', NULL, NULL, 4, 5520, 920),
(5521, 'reimburse', '/ˌriːɪmˈbɜːrs/', 'verb', '{"zh-TW":["報銷；償還"],"en":["to pay back money spent"]}', '{"prefix":{"text":"re-","meaning":"back"},"root":{"text":"im-burse","meaning":"purse (錢包)"}}', 'reimburse expenses / reimburse sb. for / reimbursement policy', '[{"en":"The company will reimburse travel expenses.","zh-TW":"公司將報銷差旅費。"},{"en":"You will be reimbursed within 30 days.","zh-TW":"你將在30天內獲得報銷。"}]', '{"noun":"reimbursement"}', NULL, 3, 5521, 53),
(5522, 'reimbursement', '/ˌriːɪmˈbɜːrsmənt/', 'noun', '{"zh-TW":["報銷；補償"],"en":["repayment for expenses incurred"]}', NULL, 'expense reimbursement / request reimbursement', '[{"en":"Submit your receipts to receive reimbursement.","zh-TW":"提交收據以獲得報銷。"},{"en":"Business travel expenses will be reimbursed within two weeks.","zh-TW":"商務旅行費用將在兩週內報銷。"}]', '{"verb":"reimburse","adjective":"reimbursed"}', NULL, 5, 5522, 614),
(5523, 'reimbursement claim', '/ˌriːɪmˈbɜːrsmənt kleɪm/', 'noun', '{"zh-TW":["報銷申請"],"en":["a request to be repaid for expenses already paid out of pocket"]}', NULL, 'submit a reimbursement claim / process a reimbursement claim', '[{"en":"Employees must submit a reimbursement claim within 30 days.","zh-TW":"員工必須在30天內提交報銷申請。"},{"en":"All reimbursement claims are reviewed by the finance department.","zh-TW":"所有報銷申請都由財務部門審查。"}]', NULL, NULL, 5, 5523, NULL),
(5524, 'reinforce', '/ˌriːɪnˈfɔːrs/', 'verb', '{"zh-TW":["加強；鞏固"],"en":["to make stronger"]}', '{"prefix":{"text":"re-","meaning":"again"},"root":{"text":"in-force","meaning":"strengthen (加強)"}}', 'reinforce the message / reinforce a policy', '[{"en":"This reinforces our commitment to quality.","zh-TW":"這強化了我們對品質的承諾。"},{"en":"Training reinforces best practices.","zh-TW":"培訓鞏固了最佳做法。"}]', '{"noun":"reinforcement"}', NULL, 3, 5524, 714),
(5525, 'reinstate', '/ˌriːɪnˈsteɪt/', 'verb', '{"zh-TW":["恢復；重新啟用"],"en":["to restore something to its previous position or status"]}', NULL, 'reinstate a policy / reinstate an employee', '[{"en":"The suspended policy was reinstated after regulatory review.","zh-TW":"暫停的政策在監管審查後恢復了。"},{"en":"The dismissed employee was reinstated following a successful appeal.","zh-TW":"被解雇的員工在成功上訴後被恢復職位。"}]', '{"noun":"reinstatement","adjective":"reinstated"}', NULL, 3, 5525, NULL),
(5526, 'reinvest', '/ˌriːɪnˈvɛst/', 'verb', '{"zh-TW":["再投資"],"en":["to invest money gained back into the same or different ventures"]}', NULL, 'reinvest profits / reinvest in the business', '[{"en":"The company decided to reinvest its profits into research.","zh-TW":"公司決定將利潤再投資於研究。"},{"en":"Reinvesting dividends can significantly grow your wealth over time.","zh-TW":"再投資股息可以隨時間大幅增加您的財富。"}]', '{"noun":"reinvestment","adjective":"reinvested"}', NULL, 3, 5526, NULL),
(5527, 'reject', '/rɪˈdʒekt/', 'verb', '{"zh-TW":["拒絕；駁回"],"en":["to refuse to accept or consider","to refuse to accept"]}', '{"prefix":{"text":"re-","meaning":"back (回)"},"root":{"text":"ject","meaning":"throw (丟)"},"logic":"丟回去，即「拒絕」。"}', 'reject an offer / reject a proposal; reject a proposal / reject an application / flat out reject', '[{"en":"The committee rejected his proposal.","zh-TW":"委員會駁回了他的提案。"},{"en":"She rejected the job offer.","zh-TW":"她拒絕了這份工作邀約。"},{"en":"The board rejected the merger proposal.","zh-TW":"董事會駁回了合併提案。"},{"en":"Her application was rejected.","zh-TW":"她的申請被拒絕了。"}]', '{"noun":"rejection"}', NULL, 2, 5527, NULL),
(5528, 'rejection', '/rɪˈdʒɛkʃən/', 'noun', '{"zh-TW":["拒絕；駁回"],"en":["the dismissal of something or someone"]}', NULL, 'face rejection / rejection letter', '[{"en":"She received a rejection letter from the university.","zh-TW":"她收到了大學的拒絕信。"},{"en":"Rejection of the proposal was unexpected but prompted a revision.","zh-TW":"提案被拒絕出乎意料，但促使了修訂。"}]', '{"verb":"reject","adjective":"rejected"}', NULL, 3, 5528, 435),
(5529, 'rejection letter', '/rɪˈdʒekʃən ˈletər/', 'noun', '{"zh-TW":["拒絕信；未錄用通知"],"en":["a letter informing a candidate or supplier that they have not been selected"]}', NULL, 'send a rejection letter / receive a rejection letter', '[{"en":"All unsuccessful candidates received a rejection letter within a week.","zh-TW":"所有未成功的候選人在一週內收到了拒絕信。"},{"en":"A professional rejection letter maintains goodwill with future applicants.","zh-TW":"專業的拒絕信與未來的申請人保持了良好關係。"}]', NULL, NULL, 5, 5529, NULL),
(5530, 'relate', '/rɪˈleɪt/', 'verb', '{"zh-TW":["與...有關","敘述"],"en":["to connect or be relevant","to tell"]}', '{"prefix":{"text":"re-","meaning":"back"},"root":{"text":"late","meaning":"carry (攜帶)"}}', 'relate to / related to / in relation to', '[{"en":"This issue relates to our earlier discussion.","zh-TW":"這問題與我們之前的討論有關。"},{"en":"The increase is related to market demand.","zh-TW":"增長與市場需求有關。"}]', '{"noun":"relation, relationship","adjective":"related, relative","adverb":"relatively"}', NULL, 2, 5530, NULL),
(5531, 'relate to', '/rɪˈleɪt tuː/', 'verb', '{"zh-TW":["與⋯有關；適用於"],"en":["to be connected with or have relevance to something"]}', NULL, 'expenses that relate to operations / results that relate to the quarter', '[{"en":"The legal matter relates to a contract dispute from 2023.","zh-TW":"該法律事項與2023年的合約糾紛有關。"},{"en":"All queries relating to billing should be directed to accounts.","zh-TW":"所有與計費相關的查詢應聯絡帳務部門。"}]', NULL, NULL, 3, 5531, NULL),
(5532, 'related party transaction', '/rɪˈleɪtɪd ˈpɑːrti trænˈzækʃən/', 'noun', '{"zh-TW":["關聯方交易"],"en":["a business transaction between parties with a prior relationship or shared interest"]}', NULL, 'disclose related party transactions / related party transaction approval', '[{"en":"All related party transactions must be disclosed in the financial statements.","zh-TW":"所有關聯方交易必須在財務報表中披露。"},{"en":"The audit committee reviewed the terms of the related party transaction.","zh-TW":"審計委員會審查了關聯方交易的條款。"}]', NULL, NULL, 5, 5532, NULL),
(5533, 'relationship', 'rɪˈleɪʃənʃɪp', 'noun', '{"zh-TW":["關係；關聯","業務關係"],"en":["a connection between people","how things are connected"]}', NULL, 'business relationship/working relationship', '[{"en":"Strong client relationships lead to success.","zh-TW":"強大的客戶關係帶來成功。"}]', '{"adjective":"relational","adverb":"relationally"}', NULL, 4, 5533, 436),
(5534, 'relationship management', '/rɪˈleɪʃənʃɪp ˈmænɪdʒmənt/', 'noun', '{"zh-TW":["關係管理"],"en":["strategies and processes for building and maintaining business relationships"]}', NULL, 'improve relationship management / customer relationship management', '[{"en":"Strong relationship management led to contract renewals.","zh-TW":"強大的關係管理帶來了合約續期。"},{"en":"CRM software supports relationship management with clients.","zh-TW":"CRM軟體支持與客戶的關係管理。"}]', NULL, NULL, 5, 5534, NULL),
(5535, 'relativism', '/ˈrelətɪvɪzəm/', 'noun', '{"zh-TW":["相對主義；相對論"],"en":["the doctrine that knowledge and values are not absolute"]}', NULL, 'moral relativism / cultural relativism / philosophical relativism', '[{"en":"Cultural relativism encourages understanding practices within their context.","zh-TW":"文化相對主義鼓勵在其脈絡中理解習俗。"},{"en":"Critics argue that relativism undermines universal ethical standards.","zh-TW":"批評者認為相對主義破壞了普世倫理標準。"}]', '{"adjective":"relativist","noun":"relativist"}', NULL, 4, 5535, NULL),
(5536, 'relay race', '/''riːleɪ reɪs/', 'noun', '{"zh-TW":["接力賽"],"en":["a race between teams in which each team member successively covers part of the total distance"]}', NULL, 'run a relay race / relay race team / anchor the relay race', '[{"en":"The relay race team passed the baton smoothly to win by half a second.","zh-TW":"接力賽隊伍順暢地交接接力棒，以半秒之差獲勝。"},{"en":"She was selected as the anchor runner for the relay race team.","zh-TW":"她被選為接力賽隊伍的最後一棒選手。"}]', NULL, NULL, 4, 5536, NULL),
(5537, 'release', '/rɪˈliːs/', 'verb', '{"zh-TW":["發布；釋放"],"en":["to make available; to set free"]}', '{"prefix":{"text":"re-","meaning":"back"},"root":{"text":"lease","meaning":"let go (放開)"}}', 'release a product / press release / release information', '[{"en":"The company will release the new product in March.","zh-TW":"公司將於三月發布新產品。"},{"en":"A press release was issued today.","zh-TW":"今天發布了新聞稿。"}]', '{"noun":"release"}', NULL, 3, 5537, 197),
(5538, 'release clause', '/rɪˈliːs klɔːz/', 'noun', '{"zh-TW":["解除條款"],"en":["a contract provision allowing one party to terminate under specific conditions"]}', NULL, 'invoke a release clause / negotiate a release clause', '[{"en":"The release clause allowed the firm to exit the lease after two years.","zh-TW":"解除條款允許公司在兩年後退出租約。"},{"en":"The release clause was triggered by the project''s failure to proceed.","zh-TW":"解除條款因項目未能推進而被觸發。"}]', NULL, NULL, 5, 5538, NULL),
(5539, 'release funds', '/rɪˈliːs fʌndz/', 'verb', '{"zh-TW":["釋放資金；撥付款項"],"en":["to make money available for use by authorizing its transfer"]}', NULL, 'release funds for a project / approve and release funds', '[{"en":"The finance committee approved and released funds for the renovation.","zh-TW":"財務委員會批准並撥付了翻新資金。"},{"en":"Funds are released in stages as project milestones are reached.","zh-TW":"隨著項目里程碑的實現，資金分階段釋放。"}]', NULL, NULL, 5, 5539, NULL),
(5540, 'relentless', '/''rɪˈlentləs/', 'adjective', '{"zh-TW":["不懈的；無情的"],"en":["oppressively constant; incessant; harsh or inflexible"]}', NULL, 'relentless pursuit / relentless pressure / relentless effort', '[{"en":"Her relentless effort finally paid off when she received the promotion.","zh-TW":"她不懈的努力最終在獲得晉升時得到了回報。"},{"en":"The team faced relentless pressure to meet the quarterly targets.","zh-TW":"團隊面臨著不斷的壓力以達到季度目標。"}]', '{"adverb":"relentlessly","noun":"relentlessness"}', NULL, 4, 5540, NULL),
(5541, 'relevant', '/ˈreləvənt/', 'adjective', '{"zh-TW":["相關的；切題的"],"en":["closely connected to the matter at hand","closely connected to the matter"]}', '{"prefix":{"text":"re-","meaning":"again (再次)"},"root":{"text":"lev","meaning":"raise (提起)"},"suffix":{"text":"-ant","meaning":"being (…的)"},"logic":"能再次被提起的重要資訊，即「相關的」。"}', 'relevant experience / relevant information / highly relevant; relevant experience / relevant to / relevant information', '[{"en":"Please include all relevant information.","zh-TW":"請包含所有相關資訊。"},{"en":"Her experience is highly relevant to this position.","zh-TW":"她的經驗與這個職位高度相關。"},{"en":"Please include all relevant experience on your resume.","zh-TW":"請在履歷中包含所有相關經驗。"},{"en":"This is not relevant to the discussion.","zh-TW":"這與討論無關。"}]', '{"noun":"relevance","adverb":"relevantly"}', NULL, 3, 5541, NULL),
(5542, 'reliable', '/rɪˈlaɪəbl/', 'adjective', '{"zh-TW":["可靠的；可信賴的"],"en":["able to be trusted"]}', '{"root":{"text":"rely","meaning":"depend (依賴)"},"suffix":{"text":"-able","meaning":"能...的"}}', 'reliable source / reliable service / highly reliable', '[{"en":"We need a reliable supplier.","zh-TW":"我們需要可靠的供應商。"},{"en":"The system has proven to be highly reliable.","zh-TW":"系統已被證明非常可靠。"}]', '{"noun":"reliability","adverb":"reliably","verb":"rely"}', NULL, 3, 5542, 437),
(5543, 'relief', '/rɪˈliːf/', 'noun', '{"zh-TW":["緩解；減輕","救濟"],"en":["the feeling of comfort after anxiety","aid given"]}', '{"prefix":{"text":"re-","meaning":"again"},"root":{"text":"lief","meaning":"lift (舉起)"}}', 'tax relief / disaster relief / to one''s relief / provide relief', '[{"en":"The tax relief benefits small businesses.","zh-TW":"稅收減免有利於小企業。"},{"en":"To our relief, the problem was resolved quickly.","zh-TW":"令我們欣慰的是，問題很快解決了。"}]', '{"verb":"relieve"}', NULL, 2, 5543, NULL),
(5544, 'relocation package', '/ˌriːloʊˈkeɪʃən ˈpækɪdʒ/', 'noun', '{"zh-TW":["搬遷方案；異地補貼"],"en":["benefits provided to an employee who moves for their job"]}', NULL, 'offer a relocation package / relocation package terms / generous relocation package', '[{"en":"The relocation package covered moving costs and temporary housing.","zh-TW":"搬遷方案涵蓋搬遷費用和臨時住房。"},{"en":"She accepted the job offer partly because of the generous relocation package.","zh-TW":"她接受工作邀請部分原因是豐厚的搬遷方案。"}]', NULL, NULL, 5, 5544, NULL),
(5545, 'reluctant', '/rɪˈlʌktənt/', 'adjective', '{"zh-TW":["不情願的","不情願的；勉強的"],"en":["unwilling and hesitant","unwilling to do something"]}', '{"prefix":{"text":"re-","meaning":"against (反對)"},"root":{"text":"luct","meaning":"struggle (掙扎)"},"suffix":{"text":"-ant","meaning":"being (…的)"},"logic":"對某事掙扎抗拒的，即「不情願的」。"}', 'reluctant to / a reluctant participant; reluctant to do / be reluctant', '[{"en":"He was reluctant to admit his mistake.","zh-TW":"他不情願承認自己的錯誤。"},{"en":"She was a reluctant participant in the debate.","zh-TW":"她是辯論中不情願的參與者。"},{"en":"He was reluctant to accept the transfer.","zh-TW":"他不情願接受調動。"},{"en":"Many employees are reluctant to change.","zh-TW":"許多員工不願意改變。"}]', '{"noun":"reluctance","adverb":"reluctantly"}', NULL, 3, 5545, NULL),
(5546, 'rely', '/rɪˈlaɪ/', 'verb', '{"zh-TW":["依賴；信賴","依賴；依靠"],"en":["to depend on with full trust","to depend on with confidence"]}', '{"prefix":{"text":"re-","meaning":"back (回)"},"root":{"text":"ly","meaning":"bind (綁)"},"logic":"被綁回到某人身上（依靠），即「依賴」。"}', 'rely on / rely heavily on; rely on / rely heavily on / reliable', '[{"en":"We rely on technology for communication.","zh-TW":"我們依賴科技來溝通。"},{"en":"You can rely on her to do a good job.","zh-TW":"你可以信賴她會做好。"},{"en":"We rely heavily on technology.","zh-TW":"我們嚴重依賴技術。"},{"en":"You can rely on our team to deliver.","zh-TW":"你可以依靠我們團隊交付。"}]', '{"adjective":"reliable","noun":"reliance","noun2":"reliability"}', NULL, 1, 5546, NULL),
(5547, 'remain', '/rɪˈmeɪn/', 'verb', '{"zh-TW":["保持；仍然是","剩餘"],"en":["to continue in the same state","to be left"]}', '{"prefix":{"text":"re-","meaning":"back"},"root":{"text":"main","meaning":"stay (停留)"}}', 'remain unchanged / remain competitive / remaining balance', '[{"en":"Prices remain stable this quarter.","zh-TW":"本季度價格保持穩定。"},{"en":"Several issues remain unresolved.","zh-TW":"幾個問題仍未解決。"}]', '{"noun":"remainder, remains","adjective":"remaining"}', NULL, 2, 5547, 198),
(5548, 'remarkable', '/rɪˈmɑːrkəbl/', 'adjective', '{"zh-TW":["卓越的；非凡的"],"en":["worthy of attention; extraordinary"]}', '{"prefix":{"text":"re-","meaning":"again"},"root":{"text":"mark","meaning":"notice (注意)"},"suffix":{"text":"-able","meaning":"能...的"}}', 'remarkable achievement / remarkable growth', '[{"en":"The company has shown remarkable growth.","zh-TW":"公司展現了非凡的增長。"},{"en":"Her performance was truly remarkable.","zh-TW":"她的表現真正非凡。"}]', '{"adverb":"remarkably"}', NULL, 4, 5548, NULL),
(5549, 'remedial class', '/''rɪˈmiːdiəl klɑːs/', 'noun', '{"zh-TW":["補救教學班；補救課程"],"en":["a class intended to help students who are struggling with the standard curriculum"]}', NULL, 'enroll in a remedial class / take a remedial class / benefit of remedial class', '[{"en":"Students who fail the placement test must take remedial math classes.","zh-TW":"未能通過分級測試的學生必須參加數學補救教學班。"},{"en":"Remedial classes helped her catch up and eventually join the mainstream program.","zh-TW":"補救課程幫助她趕上進度，最終加入主流計畫。"}]', NULL, NULL, 5, 5549, NULL);
INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(5550, 'remediation', '/rɪˌmiːdiˈeɪʃən/', 'noun', '{"zh-TW":["補救措施；修復"],"en":["the action of rectifying a problem, error, or environmental issue"]}', NULL, 'complete remediation / remediation plan', '[{"en":"The company implemented a remediation plan after the audit findings.","zh-TW":"公司在審計發現後實施了補救措施計劃。"},{"en":"Environmental remediation was required before the land could be redeveloped.","zh-TW":"在土地重新開發前需要進行環境修復。"}]', '{"verb":"remediate"}', NULL, 4, 5550, NULL),
(5551, 'remedy', '/ˈrɛmɪdi/', 'noun', '{"zh-TW":["補救措施；療法"],"en":["a solution to a problem"]}', '{"prefix":{"text":"re-","meaning":"again"},"root":{"text":"med","meaning":"heal (治療)"}}', 'find a remedy / legal remedy / remedy the situation', '[{"en":"We must find a remedy for this issue.","zh-TW":"我們必須找到解決方案。"},{"en":"Legal remedies are available.","zh-TW":"可採取法律補救措施。"}]', '{"verb":"remedy","adjective":"remedial"}', NULL, 2, 5551, NULL),
(5552, 'remember', '/rɪˈmɛmbər/', 'verb', '{"zh-TW":["記得；想起"],"en":["to have in mind","to recall"]}', NULL, 'remember to / if I remember correctly', '[{"en":"Remember to submit the report.","zh-TW":"記得提交報告。"},{"en":"If I remember correctly, the deadline is Friday.","zh-TW":"如果我沒記錯，截止日期是週五。"}]', '{"verb":"remember","noun":"remembrance"}', NULL, 3, 5552, NULL),
(5553, 'remind', '/rɪˈmaɪnd/', 'verb', '{"zh-TW":["提醒"],"en":["to cause someone to remember"]}', '{"prefix":{"text":"re-","meaning":"again"},"root":{"text":"mind","meaning":"mind (心智)"}}', 'remind sb. of / remind sb. to do / a reminder', '[{"en":"Please remind me to call the client.","zh-TW":"請提醒我打給客戶。"},{"en":"This is a reminder that reports are due Friday.","zh-TW":"這是提醒：報告週五到期。"}]', '{"noun":"reminder"}', NULL, 2, 5553, 199),
(5554, 'reminder', 'rɪˈmaɪndər', 'noun', '{"zh-TW":["提醒；提示","催促"],"en":["a message to make someone remember","a note to remind"]}', NULL, 'send a reminder/friendly reminder', '[{"en":"Please send a reminder to all attendees.","zh-TW":"請向所有出席者發送提醒。"}]', '{"verb":"remind","adjective":"reminded"}', NULL, 3, 5554, NULL),
(5555, 'remission', '/rɪˈmɪʃən/', 'noun', '{"zh-TW":["緩解；病情暫時好轉"],"en":["a temporary or permanent decrease in the severity of a disease"]}', NULL, 'go into remission / achieve remission / complete remission', '[{"en":"The patient''s leukemia went into complete remission after treatment.","zh-TW":"患者的白血病在治療後完全緩解。"},{"en":"Maintaining remission requires ongoing medication and lifestyle management.","zh-TW":"維持緩解需要持續的藥物治療和生活方式管理。"}]', '{"verb":"remit","adjective":"in remission"}', NULL, 3, 5555, NULL),
(5556, 'remittance', '/rɪˈmɪtəns/', 'noun', '{"zh-TW":["匯款；匯寄"],"en":["a sum of money sent to someone abroad"]}', NULL, 'send a remittance / remittance service', '[{"en":"She sent a monthly remittance to support her family abroad.","zh-TW":"她每月匯款支持她在國外的家人。"},{"en":"Remittance fees vary between service providers.","zh-TW":"匯款費用因服務提供商而異。"}]', '{"verb":"remit"}', NULL, 4, 5556, NULL),
(5557, 'remittance advice', '/rɪˈmɪtəns ədˈvaɪs/', 'noun', '{"zh-TW":["匯款通知；付款通知"],"en":["a document sent by the payer to notify the recipient of a payment"]}', NULL, 'send a remittance advice / include remittance advice', '[{"en":"Please find the attached remittance advice for payment made today.","zh-TW":"請查找今天已付款的隨附匯款通知。"},{"en":"Remittance advice helps the recipient match payment to the invoice.","zh-TW":"匯款通知幫助收款人將付款與發票匹配。"}]', NULL, NULL, 5, 5557, NULL),
(5558, 'remote', '/rɪˈmoʊt/', 'adjective', '{"zh-TW":["遠程的；偏遠的"],"en":["far away; operating from a distance"]}', '{"prefix":{"text":"re-","meaning":"back"},"root":{"text":"mote","meaning":"move (移動)"}}', 'remote work / remote access / remote location', '[{"en":"Most employees now work remotely.","zh-TW":"大多數員工現在遠程工作。"},{"en":"Remote access to the system is available.","zh-TW":"系統可以遠程訪問。"}]', '{"adverb":"remotely","noun":"remoteness"}', NULL, 2, 5558, NULL),
(5559, 'remote access', '/rɪˈməʊt ˈæksɛs/', 'noun', '{"zh-TW":["遠端訪問"],"en":["the ability to access a computer or network from a different location"]}', NULL, 'enable remote access / secure remote access', '[{"en":"Employees require remote access to company systems when traveling.","zh-TW":"員工在出差時需要遠端訪問公司系統。"},{"en":"Remote access must be secured with multi-factor authentication.","zh-TW":"遠端訪問必須通過多因素驗證加以保護。"}]', NULL, NULL, 5, 5559, NULL),
(5560, 'remote collaboration', '/''rɪˌməʊt kəˌlæbəˌreɪʃən/', 'noun', '{"zh-TW":["遠程協作；線上合作"],"en":["working together with colleagues or partners who are in different physical locations"]}', NULL, 'enable remote collaboration / challenge of remote collaboration / remote collaboration tool', '[{"en":"Effective remote collaboration requires clear communication and reliable technology.","zh-TW":"有效的遠程協作需要清晰的溝通和可靠的技術。"},{"en":"The company invested in tools to support remote collaboration across multiple time zones.","zh-TW":"公司投資於支持跨多個時區遠程協作的工具。"}]', '{"verb":"collaborate","adjective":"remote"}', NULL, 5, 5560, NULL),
(5561, 'remote work', '/rɪˈmoʊt wɜːrk/', 'noun', '{"zh-TW":["遠端工作；遠距工作"],"en":["working outside a traditional office environment, often from home"]}', NULL, 'remote work policy / adopt remote work / fully remote', '[{"en":"Remote work became widespread during the pandemic.","zh-TW":"疫情期間，遠端工作變得普遍。"},{"en":"The company offers remote work options to attract global talent.","zh-TW":"公司提供遠端工作選項以吸引全球人才。"}]', '{"adjective":"remote","noun":"remote worker"}', NULL, 4, 5561, NULL),
(5562, 'remove', '/rɪˈmuːv/', 'verb', '{"zh-TW":["移除；消除"],"en":["to take away"]}', '{"prefix":{"text":"re-","meaning":"back"},"root":{"text":"move","meaning":"move (移動)"}}', 'remove from / remove obstacles / remove barriers', '[{"en":"Please remove your belongings from the desk.","zh-TW":"請把你的物品從桌上移走。"},{"en":"We need to remove barriers to entry.","zh-TW":"我們需要消除進入障礙。"}]', '{"noun":"removal","adjective":"removable"}', NULL, 2, 5562, NULL),
(5563, 'remunerate', '/rɪˈmjuːnəreɪt/', 'verb', '{"zh-TW":["酬勞；報酬"],"en":["to pay someone for services rendered"]}', NULL, 'remunerate fairly / remunerate employees / remunerate adequately', '[{"en":"The policy ensures all employees are remunerated fairly.","zh-TW":"該政策確保所有員工得到公平酬勞。"},{"en":"The contract specifies how consultants are to be remunerated.","zh-TW":"合約規定了顧問的酬勞方式。"}]', '{"noun":"remuneration","adjective":"remunerative"}', NULL, 4, 5563, NULL),
(5564, 'remuneration', '/rɪˌmjuːnəˈreɪʃən/', 'noun', '{"zh-TW":["報酬；薪資"],"en":["payment or reward for work or services provided"]}', NULL, 'total remuneration / remuneration package / executive remuneration', '[{"en":"The remuneration committee sets executive pay levels.","zh-TW":"薪酬委員會確定高管薪資水準。"},{"en":"Remuneration should reflect the employee''s level of responsibility.","zh-TW":"報酬應反映員工的責任水準。"}]', '{"verb":"remunerate","adjective":"remunerative"}', NULL, 4, 5564, 922),
(5565, 'remuneration package', '/rɪˌmjuːnəˈreɪʃən ˈpækɪdʒ/', 'noun', '{"zh-TW":["薪酬套餐"],"en":["the total pay and benefits offered to an employee in return for their work"]}', NULL, 'offer a remuneration package / review the remuneration package', '[{"en":"The executive''s remuneration package includes salary, bonus, and pension.","zh-TW":"高管的薪酬套餐包括薪資、獎金和退休金。"},{"en":"A competitive remuneration package helps attract senior talent.","zh-TW":"有競爭力的薪酬套餐有助於吸引高層人才。"}]', NULL, NULL, 5, 5565, NULL),
(5566, 'renegotiate', '/ˌriːnɪˈɡoʊʃieɪt/', 'verb', '{"zh-TW":["重新談判；重新協商"],"en":["to negotiate the terms of an existing agreement again"]}', NULL, 'renegotiate a contract / renegotiate payment terms', '[{"en":"The company renegotiated its supplier contracts to reduce costs.","zh-TW":"公司重新談判了供應商合約以降低成本。"},{"en":"Loan terms were renegotiated to improve cash flow.","zh-TW":"貸款條款重新談判以改善現金流。"}]', '{"noun":"renegotiation","adjective":"renegotiated"}', NULL, 4, 5566, NULL),
(5567, 'renew', '/rɪˈnjuː/', 'verb', '{"zh-TW":["更新；續約"],"en":["to make valid for another period"]}', '{"prefix":{"text":"re-","meaning":"again"},"root":{"text":"new","meaning":"new (新)"}}', 'renew a contract / renew a subscription / renewal date', '[{"en":"Don''t forget to renew your license.","zh-TW":"別忘了更新你的執照。"},{"en":"The contract was renewed for another year.","zh-TW":"合約續約了一年。"}]', '{"noun":"renewal","adjective":"renewable"}', NULL, 2, 5567, 716),
(5568, 'renewable energy', '/rɪˈnjuːəbəl ˈɛnərdʒi/', 'noun', '{"zh-TW":["再生能源；可再生能源"],"en":["energy from a source that is not depleted when used"]}', NULL, 'invest in renewable energy / renewable energy source', '[{"en":"Solar and wind are popular forms of renewable energy.","zh-TW":"太陽能和風能是受歡迎的再生能源形式。"},{"en":"Renewable energy is becoming more affordable each year.","zh-TW":"再生能源每年變得越來越實惠。"}]', '{"adjective":"renewable"}', NULL, 5, 5568, NULL),
(5569, 'renewable energy source', '/''rɪˌnjuːəbəl ˌenərʒi sɔːrs/', 'noun', '{"zh-TW":["可再生能源"],"en":["an energy source that is naturally replenished, such as solar, wind, or hydropower"]}', NULL, 'invest in renewable energy sources / switch to renewable energy sources / develop renewable energy sources', '[{"en":"The government increased investment in renewable energy sources to reduce carbon emissions.","zh-TW":"政府增加了對可再生能源的投資，以減少碳排放。"},{"en":"Renewable energy sources are expected to supply the majority of global power by mid-century.","zh-TW":"預計到本世紀中葉，可再生能源將供應全球大部分電力。"}]', '{"adjective":"renewable"}', NULL, 5, 5569, NULL),
(5570, 'renewable portfolio standard', '/rɪˈnjuːəbəl pɔːtˈfəʊliəʊ ˈstændərd/', 'noun', '{"zh-TW":["再生能源組合標準"],"en":["a regulatory mandate requiring utilities to generate a percentage of electricity from renewables"]}', NULL, 'meet renewable portfolio standard / implement renewable portfolio standard / renewable portfolio standard targets', '[{"en":"The state''s renewable portfolio standard requires forty percent clean energy by 2030.","zh-TW":"該州的再生能源組合標準要求到2030年使用百分之四十的清潔能源。"},{"en":"Renewable portfolio standards have driven significant growth in wind and solar power.","zh-TW":"再生能源組合標準推動了風能和太陽能的顯著增長。"}]', NULL, NULL, 5, 5570, NULL),
(5571, 'renewable resource', '/rɪˈnjuːəbəl rɪˈzɔːrs/', 'noun', '{"zh-TW":["可再生資源"],"en":["a natural resource that is replenished naturally over time"]}', NULL, 'use renewable resources / conserve renewable resources', '[{"en":"Wind and solar power are examples of renewable resources.","zh-TW":"風能和太陽能是可再生資源的例子。"},{"en":"Transitioning to renewable resources is essential for sustainability.","zh-TW":"過渡到可再生資源對永續發展至關重要。"}]', NULL, NULL, 5, 5571, NULL),
(5572, 'renewal', 'rɪˈnjuːəl', 'noun', '{"zh-TW":["續約；更新","復甦"],"en":["the act of renewing","continuing after a period"]}', NULL, 'contract renewal/subscription renewal', '[{"en":"Please confirm your contract renewal.","zh-TW":"請確認您的合約續簽。"}]', '{"verb":"renew","adjective":"renewable"}', NULL, 3, 5572, 439),
(5573, 'renewal clause', '/rɪˈnjuːəl klɔːz/', 'noun', '{"zh-TW":["續約條款"],"en":["a contract provision allowing automatic or optional renewal of an agreement"]}', NULL, 'include a renewal clause / exercise the renewal clause', '[{"en":"The lease included a renewal clause allowing a 3-year extension.","zh-TW":"租約包含了允許延長3年的續約條款。"},{"en":"The client exercised the renewal clause before the contract expired.","zh-TW":"客戶在合約到期前行使了續約條款。"}]', NULL, NULL, 5, 5573, NULL),
(5574, 'renewal rate', '/rɪˈnjuːəl reɪt/', 'noun', '{"zh-TW":["續約率"],"en":["the percentage of customers who renew a contract or subscription"]}', NULL, 'improve renewal rate / track renewal rate', '[{"en":"The software''s renewal rate increased after new features were added.","zh-TW":"添加新功能後軟件的續約率提高了。"},{"en":"A high renewal rate indicates strong customer satisfaction.","zh-TW":"高續約率表明客戶滿意度高。"}]', NULL, NULL, 4, 5574, NULL),
(5575, 'renewal terms', '/rɪˈnjuːəl tɜːrmz/', 'noun', '{"zh-TW":["續約條款"],"en":["the conditions under which a contract will be extended"]}', NULL, 'negotiate renewal terms / review renewal terms', '[{"en":"The supplier proposed new pricing as part of the renewal terms.","zh-TW":"供應商提出了新定價作為續約條款的一部分。"},{"en":"Renewal terms were accepted without modification by both parties.","zh-TW":"雙方未作修改地接受了續約條款。"}]', NULL, NULL, 5, 5575, NULL),
(5576, 'renovate', '/ˈrɛnəveɪt/', 'verb', '{"zh-TW":["翻新；修繕","翻修"],"en":["to repair and improve a building","to restore to good condition"]}', '{"prefix":{"text":"re-","meaning":"again"},"root":{"text":"nov","meaning":"new (新)"},"suffix":{"text":"-ate","meaning":"使..."}}', 'renovate the office / recently renovated; renovate the building / newly renovated', '[{"en":"The office was recently renovated.","zh-TW":"辦公室最近進行了翻新。"},{"en":"They plan to renovate the building.","zh-TW":"他們計劃翻新大樓。"},{"en":"The hotel was recently renovated.","zh-TW":"酒店最近翻新了。"},{"en":"Plans to renovate the office were approved.","zh-TW":"翻新辦公室的計劃已獲批。"}]', '{"noun":"renovation"}', NULL, 3, 5576, NULL),
(5577, 'renovation', '/ˌrenəˈveɪʃən/', 'noun', '{"zh-TW":["翻新；整修"],"en":["the process of improving or restoring a building to good condition"]}', NULL, 'property renovation / renovation project / renovation costs', '[{"en":"The office underwent major renovation over the summer.","zh-TW":"辦公室在夏季進行了大規模翻新。"},{"en":"Renovation costs were higher than initially budgeted.","zh-TW":"翻新費用高於最初預算。"}]', '{"verb":"renovate","adjective":"renovated"}', NULL, 4, 5577, NULL),
(5578, 'rent', '/rɛnt/', 'noun', '{"zh-TW":["租金"],"en":["payment for use of property"]}', NULL, 'pay rent / rent out / for rent / rental agreement', '[{"en":"Office rent has increased significantly.","zh-TW":"辦公室租金大幅上漲。"},{"en":"The apartment is available for rent.","zh-TW":"公寓可供出租。"}]', '{"verb":"rent","noun":"rental, renter"}', NULL, 1, 5578, NULL),
(5579, 'rent stabilization', '/''rent ˌsteɪbɪlaɪˌzeɪʃən/', 'noun', '{"zh-TW":["租金穩定；租金管制"],"en":["a policy that limits how much landlords can increase rent for existing tenants"]}', NULL, 'implement rent stabilization / rent stabilization policy / benefit of rent stabilization', '[{"en":"Rent stabilization policies help protect low-income tenants from being priced out of their homes.","zh-TW":"租金穩定政策有助於保護低收入租戶免於因租金上漲而被迫搬離。"},{"en":"Critics argue that rent stabilization discourages property maintenance and investment.","zh-TW":"批評者認為，租金穩定政策阻礙了物業維護和投資。"}]', '{"verb":"stabilize","noun":"stabilization"}', NULL, 5, 5579, NULL),
(5580, 'rental agreement', '/''rentəl əˌɡriːmənt/', 'noun', '{"zh-TW":["租賃協議；租約"],"en":["a contract between a landlord and tenant outlining the terms and conditions of renting a property"]}', NULL, 'sign a rental agreement / review a rental agreement / rental agreement terms', '[{"en":"She carefully reviewed the rental agreement before signing to ensure the terms were fair.","zh-TW":"她在簽署租賃協議前仔細審查，確保條款公平。"},{"en":"The rental agreement specifies that no pets are allowed in the property.","zh-TW":"租賃協議規定該房產不允許養寵物。"}]', '{"noun":"rental","verb":"rent"}', NULL, 5, 5580, NULL),
(5581, 'rental contract', '/''rentəl ˌkɒntrækt/', 'noun', '{"zh-TW":["租賃合同；租約"],"en":["a legal agreement between a landlord and tenant that sets out the terms of renting a property"]}', NULL, 'sign a rental contract / renew a rental contract / breach a rental contract', '[{"en":"Before moving in, she carefully read through the rental contract.","zh-TW":"搬入之前，她仔細閱讀了租賃合同。"},{"en":"The rental contract prohibited pets and required two months'' notice before vacating.","zh-TW":"租賃合同禁止飼養寵物，並要求在搬出前兩個月通知。"}]', NULL, NULL, 5, 5581, NULL),
(5582, 'rental income', '/''rentəl ˌɪŋkʌm/', 'noun', '{"zh-TW":["租金收入；房租收入"],"en":["money received from tenants for the use of a property"]}', NULL, 'earn rental income / report rental income / rental income tax', '[{"en":"She invested in a second property to generate a steady stream of rental income.","zh-TW":"她投資了第二套房產，以產生穩定的租金收入。"},{"en":"Rental income must be declared to the tax authorities each year.","zh-TW":"租金收入每年必須向稅務機關申報。"}]', NULL, NULL, 5, 5582, NULL),
(5583, 'rental market', '/''rentəl ˌmɑːrkɪt/', 'noun', '{"zh-TW":["租賃市場；租房市場"],"en":["the sector of the housing market concerned with renting rather than buying properties"]}', NULL, 'tight rental market / rental market conditions / rental market analysis', '[{"en":"The tight rental market pushed rents to record highs in major cities.","zh-TW":"緊繃的租賃市場將主要城市的租金推至歷史新高。"},{"en":"An oversupply of apartments cooled the rental market significantly.","zh-TW":"公寓供應過剩大幅冷卻了租賃市場。"}]', NULL, NULL, 5, 5583, NULL),
(5584, 'rental yield', '/''rentəl jiːld/', 'noun', '{"zh-TW":["租金回報率；租賃收益"],"en":["the annual income from a property expressed as a percentage of its value"]}', NULL, 'calculate rental yield / high rental yield / rental yield comparison', '[{"en":"Investors look for properties with a rental yield of at least five percent.","zh-TW":"投資者尋找租金回報率至少為百分之五的房產。"},{"en":"The rental yield on the downtown apartment was much higher than suburban properties.","zh-TW":"市中心公寓的租金回報率遠高於郊區房產。"}]', NULL, NULL, 4, 5584, NULL),
(5585, 'reorder point', '/ˌriːˈɔːrdər pɔɪnt/', 'noun', '{"zh-TW":["再訂購點；補貨觸發點"],"en":["the inventory level at which a new order should be placed"]}', NULL, 'set the reorder point / reach the reorder point', '[{"en":"Stock fell below the reorder point, triggering a new order.","zh-TW":"庫存降至再訂購點以下，觸發了新訂單。"},{"en":"The reorder point accounts for lead time and average demand.","zh-TW":"再訂購點考慮了前置時間和平均需求。"}]', NULL, NULL, 5, 5585, NULL),
(5586, 'reorganize', 'riːˈɔːrɡənaɪz', 'verb', '{"zh-TW":["重組；重新整理","調整"],"en":["to arrange differently","to restructure"]}', NULL, 'reorganize a department/reorganize files', '[{"en":"Management decided to reorganize the team.","zh-TW":"管理層決定重組團隊。"}]', '{"noun":"reorganization","adjective":"reorganized"}', NULL, 4, 5586, NULL),
(5587, 'repair', '/rɪˈpɛr/', 'verb', '{"zh-TW":["修理；修復"],"en":["to fix something broken"]}', '{"prefix":{"text":"re-","meaning":"again"},"root":{"text":"pair","meaning":"prepare (準備)"}}', 'repair damage / under repair / repair costs', '[{"en":"The equipment is being repaired.","zh-TW":"設備正在維修中。"},{"en":"Repair costs exceeded our estimates.","zh-TW":"修理費用超出了我們的估計。"}]', '{"noun":"repair, reparation"}', NULL, 2, 5587, 54),
(5588, 'repay', '/rɪˈpeɪ/', 'verb', '{"zh-TW":["償還；歸還"],"en":["to pay back money that was borrowed"]}', NULL, 'repay a loan / repay debt / repay in full', '[{"en":"She repaid the business loan ahead of schedule.","zh-TW":"她提前償還了商業貸款。"},{"en":"The investment was repaid with a 15% return within two years.","zh-TW":"投資在兩年內以15%的回報率得到了償還。"}]', '{"noun":"repayment","adjective":"repaid"}', NULL, 2, 5588, NULL),
(5589, 'repayment plan', '/''rɪˌpeɪmənt plæn/', 'noun', '{"zh-TW":["還款計劃；還款方案"],"en":["a schedule for repaying a debt over time in installments"]}', NULL, 'agree on a repayment plan / follow a repayment plan / set up a repayment plan', '[{"en":"She negotiated a repayment plan with the bank after falling behind on mortgage payments.","zh-TW":"她在落後于按揭還款後與銀行協商了一個還款計劃。"},{"en":"A structured repayment plan helps borrowers manage debt without financial stress.","zh-TW":"有結構的還款計劃幫助借款人在不承受財務壓力的情況下管理債務。"}]', NULL, NULL, 5, 5589, NULL),
(5590, 'repayment schedule', '/rɪˈpeɪmənt ˈʃedjuːl/', 'noun', '{"zh-TW":["還款計劃；還款時間表"],"en":["a timetable detailing when and how much of a loan will be repaid"]}', NULL, 'set a repayment schedule / adhere to the repayment schedule', '[{"en":"The bank approved a flexible repayment schedule tied to revenue.","zh-TW":"銀行批准了與收入掛鉤的彈性還款計劃。"},{"en":"Missing payments on the repayment schedule triggers penalty clauses.","zh-TW":"未按還款計劃支付款項觸發了罰款條款。"}]', NULL, NULL, 5, 5590, NULL),
(5591, 'repeat order', '/rɪˈpiːt ˈɔːrdər/', 'noun', '{"zh-TW":["重複訂單；回頭訂單"],"en":["a subsequent order from a customer who has previously purchased the same product"]}', NULL, 'place a repeat order / encourage repeat orders', '[{"en":"The product''s quality led to a high rate of repeat orders.","zh-TW":"產品的品質帶來了高比率的重複訂單。"},{"en":"Repeat orders are more cost-effective than acquiring new customers.","zh-TW":"重複訂單比獲取新客戶更具成本效益。"}]', NULL, NULL, 4, 5591, NULL),
(5592, 'repercussion', '/''riːpərˌkʌʃən/', 'noun', '{"zh-TW":["反響；後果；影響"],"en":["an unintended consequence occurring some time after an event or action"]}', NULL, 'face repercussions / consider repercussions / serious repercussion', '[{"en":"The decision to cut costs had repercussions on product quality and customer satisfaction.","zh-TW":"削減成本的決定對產品質量和客戶滿意度產生了影響。"},{"en":"Ignoring employee feedback can have serious long-term repercussions for morale.","zh-TW":"忽視員工反饋可能對士氣產生嚴重的長期影響。"}]', NULL, NULL, 4, 5592, NULL),
(5593, 'repetition', '/''repɪˈtɪʃən/', 'noun', '{"zh-TW":["重複；組數中的次數"],"en":["the action of doing something again; in fitness, one complete movement of an exercise"]}', NULL, 'do ten repetitions / repetition and sets / controlled repetition', '[{"en":"Each set consisted of ten repetitions of the exercise.","zh-TW":"每組包含十次重複的練習動作。"},{"en":"Focus on quality of movement rather than the number of repetitions.","zh-TW":"專注於動作質量，而不是重複次數的多少。"}]', '{"verb":"repeat","adjective":"repetitive"}', NULL, 4, 5593, NULL),
(5594, 'replace', '/rɪˈpleɪs/', 'verb', '{"zh-TW":["取代；更換"],"en":["to put something new in place of"]}', '{"prefix":{"text":"re-","meaning":"again"},"root":{"text":"place","meaning":"place (放置)"}}', 'replace with / replace sb. / find a replacement', '[{"en":"We will replace the old system with a new one.","zh-TW":"我們將用新系統取代舊系統。"},{"en":"She was hired to replace the former manager.","zh-TW":"她被聘來接替前任經理。"}]', '{"noun":"replacement","adjective":"replaceable"}', NULL, 3, 5594, 200),
(5595, 'replacement', 'rɪˈpleɪsmənt', 'noun', '{"zh-TW":["更換；替代品","接替者"],"en":["someone or something substituted","the act of replacing"]}', NULL, 'find a replacement/product replacement', '[{"en":"The replacement part arrived yesterday.","zh-TW":"替換零件昨天到達了。"}]', '{"verb":"replace","adjective":"replaceable"}', NULL, 4, 5595, 615),
(5596, 'replenishment', '/rɪˈplenɪʃmənt/', 'noun', '{"zh-TW":["補貨；補充"],"en":["restoring a stock of goods to an adequate level"]}', NULL, 'schedule replenishment / automatic replenishment / stock replenishment', '[{"en":"Automated replenishment reduces the risk of stockouts.","zh-TW":"自動補貨降低了缺貨的風險。"},{"en":"The replenishment order was placed as soon as inventory hit the reorder point.","zh-TW":"庫存一觸及再訂購點就立即下達了補貨訂單。"}]', '{"verb":"replenish","adjective":"replenished"}', NULL, 5, 5596, NULL),
(5597, 'replicate', '/ˈreplɪkeɪt/', 'verb', '{"zh-TW":["複製；重複驗證"],"en":["to make an exact copy; to repeat an experiment to verify results"]}', NULL, 'replicate results / replicate a study / replicate the model', '[{"en":"Scientists must be able to replicate their experiments.","zh-TW":"科學家必須能夠重複驗證他們的實驗。"},{"en":"The findings could not be replicated in subsequent studies.","zh-TW":"這些發現在後續研究中無法被重複驗證。"}]', '{"noun":"replication","adjective":"replicable"}', NULL, 3, 5597, NULL),
(5598, 'replication', '/ˌreplɪˈkeɪʃən/', 'noun', '{"zh-TW":["重複驗證；複製"],"en":["the action of copying or reproducing something; repetition of an experiment"]}', NULL, 'replication of results / replication study / direct replication', '[{"en":"Replication is a cornerstone of the scientific method.","zh-TW":"重複驗證是科學方法的基石。"},{"en":"The replication crisis has challenged findings in social psychology.","zh-TW":"重複驗證危機挑戰了社會心理學的研究結果。"}]', '{"verb":"replicate","adjective":"replicable"}', NULL, 4, 5598, NULL),
(5599, 'reply', 'rɪˈplaɪ', 'noun', '{"zh-TW":["回覆；答覆","回應"],"en":["an answer to a message","a response"]}', NULL, 'await a reply/in reply to', '[{"en":"We are waiting for your reply.","zh-TW":"我們正在等待您的回覆。"}]', '{"verb":"reply","adjective":"replying"}', NULL, 2, 5599, NULL);